UPDATE users SET role = COALESCE(?1, role), language = COALESCE(?2, language), ban_until = CASE WHEN ?3 = 1 THEN ?4 ELSE ban_until END, updated_at = CASE WHEN ?2 IS NOT NULL AND language <> ?2 THEN max(updated_at + 1, CAST(unixepoch('subsec') * 1000000 AS INTEGER)) ELSE updated_at END WHERE id = ?5 AND (?2 IS NULL OR language = ?2 OR updated_at < 9223372036854775807) RETURNING id;